window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_19", [
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. गयासुद्दीन तुगलक मकबरा   B. बीबी का मकबरा (औरंगाबाद)\nC. इकबालनामा-ए-जहाँगीरी   D. एत्मादुद्दौला का मकबरा (आगरा)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["बीबी का मकबरा (औरंगाबाद)","गयासुद्दीन तुगलक मकबरा","एत्मादुद्दौला का मकबरा (आगरा)","इकबालनामा-ए-जहाँगीरी"],"correct":1,"explanation":"गयासुद्दीन तुगलक मकबरा (1325 ई.), एत्मादुद्दौला का मकबरा (आगरा) (1626 ई.), इकबालनामा-ए-जहाँगीरी (17वीं सदी ई.), बीबी का मकबरा (औरंगाबाद) (1660 ई.)। अतः सर्वप्रथम गयासुद्दीन तुगलक मकबरा।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. चोल सम्राट राजराज प्रथम एवं राजेंद्र प्रथम   B. अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार\nC. बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)   D. बरार (इमादशाही) व बीदर (बरीदशाही)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["बरार (इमादशाही) व बीदर (बरीदशाही)","अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार","बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)","चोल सम्राट राजराज प्रथम एवं राजेंद्र प्रथम"],"correct":2,"explanation":"चोल सम्राट राजराज प्रथम एवं राजेंद्र प्रथम (1014-1044 ई.), अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार (1296-1316 ई.), बरार (इमादशाही) व बीदर (बरीदशाही) (1490 ई.), बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529) (1526 ई.)। अतः सबसे अंत में बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।\nकथन-2: सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-इंशा' का ऐतिहासिक संबंध 'धार्मिक मामले, वजीफे व राजनयिक/विदेश पत्राचार' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।)। कथन-2 गलत है — 'दीवान-ए-इंशा' का सही संबंध 'शाही पत्राचार, फरमान व अभिलेख विभाग' से था — दीवान-ए-इंशा सुल्तान के राजकीय फरमानों व प्रांतीय पत्राचार का प्रबंधन करता था।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।\nकथन-2: मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'रहीम दोहावली / प्रेमवाटिका' का ऐतिहासिक संबंध 'मोतमिद खाँ' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।)। कथन-2 गलत है — 'रहीम दोहावली / प्रेमवाटिका' का सही संबंध 'अब्दुर्रहीम खानखाना एवं रसखान (हिंदी-ब्रज काव्य)' से था — बैरम खाँ के पुत्र रहीम ने नीति दोहे व बरवै रचे तथा रसखान ने कृष्ण भक्ति के सवैये लिखे।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. बीबी का मकबरा (औरंगाबाद) : औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)\n2. अटाला मस्जिद (जौनपुर) : भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\n3. गयासुद्दीन तुगलक मकबरा : ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा\n4. एत्मादुद्दौला का मकबरा (आगरा) : नूरजहाँ (जहाँगीर काल, 1626)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'अटाला मस्जिद (जौनपुर)' का सही संबंध 'इब्राहिम शाह शर्की ('पूर्व का सिराज')' से है (न कि 'भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)' से)। 1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है।"},
  {"q":"[UPSC Prelims पैटर्न — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अटाला मस्जिद (जौनपुर) : इब्राहिम शाह शर्की ('पूर्व का सिराज')\n2. बीबी का मकबरा (औरंगाबाद) : औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)\n3. सासाराम झील मकबरा : शेरशाह सूरी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है।) युग्म 2 सही (औरंगजेब की पत्नी दिलरास बानो बेगम की स्मृति में 1651-61/78 के दौरान बीबी का मकबरा बना।) युग्म 3 सही (बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है।)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'हल्दीघाटी युद्ध (1576 ई.)' का ऐतिहासिक संबंध 'औरंगजेब व मुराद बनाम दारा शिकोह' से था।\n2. 1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।\n3. शकरखेड़ा युद्ध (1724) के बाद निजाम-उल-मुल्क ने दक्कन में स्वतंत्र हैदराबाद राज्य की नींव रखी।\n4. अल-बरूनी ने 11वीं सदी में भारत की विद्या, धर्म, विज्ञान व समाज पर 'किताब-उल-हिन्द' लिखी।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'हल्दीघाटी युद्ध (1576 ई.)' का सही संबंध 'महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)' से था — 18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — मुगलकालीन प्रमुख युद्ध] सूची-I को सूची-II से सुमेलित कीजिए:\nA. खानवा युद्ध (1527 ई.)   |   1. नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\nB. सामूगढ़ का युद्ध (1658 ई.)   |   2. बाबर बनाम राणा सांगा (मेवाड़)\nC. करनाल का युद्ध (1739 ई.)   |   3. शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\nD. चौसा का युद्ध (1539 ई.)   |   4. औरंगजेब व मुराद बनाम दारा शिकोह","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3"],"correct":3,"explanation":"सही सुमेलन: खानवा युद्ध (1527 ई.) (बाबर बनाम राणा सांगा (मेवाड़)), सामूगढ़ का युद्ध (1658 ई.) (औरंगजेब व मुराद बनाम दारा शिकोह), करनाल का युद्ध (1739 ई.) (नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'), चौसा का युद्ध (1539 ई.) (शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: शेरशाह सूरी ने मुगल अकबर के प्रशासनिक ढाँचे का अग्रदूत बनकर चाँदी का मानक 'रुपया' चलाया, जो ब्रिटिश काल तक भारतीय मुद्रा का आधार बना रहा।\nकथन-2: शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) शेरशाह सूरी ने मुगल अकबर के प्रशासनिक ढाँचे का अग्रदूत बनकर चाँदी का मानक 'रुपया' चलाया, जो ब्रिटिश काल तक भारतीय मुद्रा का आधार बना रहा। (2) शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — मध्यकालीन स्थापत्य एवं निर्माता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. अटाला मस्जिद (जौनपुर)   |   1. भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\nB. सिकंदर लोदी का मकबरा (1517)   |   2. अलाउद्दीन खिलजी\nC. सासाराम झील मकबरा   |   3. इब्राहिम शाह शर्की ('पूर्व का सिराज')\nD. अलाई दरवाजा (1311 ई.)   |   4. शेरशाह सूरी","options":["A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"correct":3,"explanation":"सही सुमेलन: अटाला मस्जिद (जौनपुर) (इब्राहिम शाह शर्की ('पूर्व का सिराज')), सिकंदर लोदी का मकबरा (1517) (भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)), सासाराम झील मकबरा (शेरशाह सूरी), अलाई दरवाजा (1311 ई.) (अलाउद्दीन खिलजी)।"},
  {"q":"[UPSC Prelims पैटर्न — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सासाराम झील मकबरा : शेरशाह सूरी\n2. सिकंदर लोदी का मकबरा (1517) : भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\n3. अलाई दरवाजा (1311 ई.) : अलाउद्दीन खिलजी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है।) युग्म 2 सही (इब्राहिम लोदी द्वारा बनवाया गया सिकंदर लोदी का मकबरा मकबरों के 'उद्यान युग' की शुरुआत करता है।) युग्म 3 सही (अलाउद्दीन खिलजी ने कुव्वत-उल-इस्लाम मस्जिद के प्रवेश द्वार के रूप में अलाई दरवाजा बनवाया।)।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. गुरु रामदास (चौथे गुरु)   2. बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें\n3. हैदराबाद राज्य (आसफजाही)   4. एकशरण संप्रदाय (असम)","options":["एकशरण संप्रदाय (असम) → बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें → गुरु रामदास (चौथे गुरु) → हैदराबाद राज्य (आसफजाही)","बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें → एकशरण संप्रदाय (असम) → गुरु रामदास (चौथे गुरु) → हैदराबाद राज्य (आसफजाही)","बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें → एकशरण संप्रदाय (असम) → हैदराबाद राज्य (आसफजाही) → गुरु रामदास (चौथे गुरु)","बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें → गुरु रामदास (चौथे गुरु) → एकशरण संप्रदाय (असम) → हैदराबाद राज्य (आसफजाही)"],"correct":1,"explanation":"सही कालानुक्रम: बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें (1347 ई.), एकशरण संप्रदाय (असम) (15वीं-16वीं सदी), गुरु रामदास (चौथे गुरु) (1577 ई.), हैदराबाद राज्य (आसफजाही) (1724 ई.)"},
  {"q":"[UPSC Prelims पैटर्न — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों पर विचार कीजिए:\n1. खानवा युद्ध (1527 ई.) : बाबर बनाम राणा सांगा (मेवाड़)\n2. सामूगढ़ का युद्ध (1658 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\n3. हल्दीघाटी युद्ध (1576 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।) युग्म 2 गलत (सही: सामूगढ़ का युद्ध (1658 ई.) — औरंगजेब व मुराद बनाम दारा शिकोह)। युग्म 3 गलत (सही: हल्दीघाटी युद्ध (1576 ई.) — महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ))।"},
  {"q":"ऐतिहासिक संदर्भ में 'पानीपत II (1556 — हेमू पराजित); दास प्रथा अंत (1562), तीर्थयात्रा कर अंत (1563), जजिया अंत (1564); हल्दीघाटी (1576 — महाराणा प्रताप बनाम मानसिंह-आसफ खाँ)' (राजनीतिक विस्तार) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)","हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)","जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा","अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान"],"correct":3,"explanation":"गुजरात अभियान के दौरान अकबर ने सर्वप्रथम पुर्तगालियों से भेंट की तथा समुद्र देखा। 1560-62 के दौर को 'पेटीकोट शासन' (महाम अनगा प्रभाव) भी कहा जाता है।"},
  {"q":"1527 ई. का 'खानवा का युद्ध' बाबर और किस राजपूत महानायक के मध्य लड़ा गया?","options":["शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय","बाबर बनाम राणा सांगा (मेवाड़)","महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)","औरंगजेब व मुराद बनाम दारा शिकोह"],"correct":1,"explanation":"17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया। इस विजय के बाद बाबर ने 'गाजी' की उपाधि धारण की।"},
  {"q":"'अकबर की राजपूत नीति, नवरत्न व मनसबदारी के नियम' के ऐतिहासिक संदर्भ में 'तीन मनसबदार श्रेणियाँ' निम्नलिखित में से क्या है?","options":["'चारबाग', 'पित्रादुरा' (संगमरमर में कीमती रत्नों की जड़ाई — एत्मादुद्दौला व ताजमहल), 'पिश्तक' (विशाल मेहराबी प्रवेशद्वार), अर्ध-प्याजी गुंबद","सूबा (सूबेदार व प्रांतीय दीवान नियंत्रण संतुलन), सरकार/जिला (फौजदार व अमलगुजार), परगना (शिकदार व आमिल), ग्राम (मुकद्दम व पटवारी)","अबुल फजल ('अकबरनामा'/'आइन-ए-अकबरी'), फैजी, तानसेन, बीरबल (प्रथम व एकमात्र हिंदू जिसने दीन-ए-इलाही स्वीकार किया), टोडरमल, मानसिंह, रहीम, फकीर अजीउद्दीन, मुल्ला दो प्याजा","प्रथम श्रेणी (सवार = जात), द्वितीय श्रेणी (सवार >= जात/2), तृतीय श्रेणी (सवार < जात/2); 'ख्वाजा सरा' व 'मीर-ए-बहर' नौका विभाग"],"correct":3,"explanation":"जहाँगीर ने बिना 'जात' बढ़ाए घुड़सवार बढ़ाने हेतु 'दु-अस्पा सिह-अस्पा' प्रणाली शुरू की, जबकि शाहजहाँ ने वास्तविक सैनिक खर्च व आय के अंतर पर 'माहवार' (महीनावार) अनुपात लागू किया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — मध्यकालीन स्थापत्य एवं निर्माता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. अटाला मस्जिद (जौनपुर)   |   1. ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा\nB. गयासुद्दीन तुगलक मकबरा   |   2. शेरशाह सूरी\nC. अलाई दरवाजा (1311 ई.)   |   3. इब्राहिम शाह शर्की ('पूर्व का सिराज')\nD. सासाराम झील मकबरा   |   4. अलाउद्दीन खिलजी","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-4, D-2"],"correct":0,"explanation":"सही सुमेलन: अटाला मस्जिद (जौनपुर) (इब्राहिम शाह शर्की ('पूर्व का सिराज')), गयासुद्दीन तुगलक मकबरा (ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा), अलाई दरवाजा (1311 ई.) (अलाउद्दीन खिलजी), सासाराम झील मकबरा (शेरशाह सूरी)।"},
  {"q":"[UPSC Prelims पैटर्न — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों पर विचार कीजिए:\n1. हल्दीघाटी युद्ध (1576 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\n2. चौसा का युद्ध (1539 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n3. करनाल का युद्ध (1739 ई.) : औरंगजेब व मुराद बनाम दारा शिकोह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।) युग्म 2 सही (बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।) युग्म 3 गलत (सही: करनाल का युद्ध (1739 ई.) — नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला')।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'चौसा का युद्ध (1539 ई.)' का ऐतिहासिक संबंध 'महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)' से था।\n2. बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया।\n3. 16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया।\n4. तुलुव सम्राट कृष्णदेवराय ने तेलुगु में 'आमुक्तमाल्यद' लिखा जिसमें प्रशासन व कृषि व्यापार के सिद्धांत भी हैं।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'चौसा का युद्ध (1539 ई.)' का सही संबंध 'शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय' से था — बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. सामूगढ़ का युद्ध (1658 ई.) : औरंगजेब व मुराद बनाम दारा शिकोह\n2. हल्दीघाटी युद्ध (1576 ई.) : बाबर बनाम राणा सांगा (मेवाड़)\n3. चौसा का युद्ध (1539 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n4. करनाल का युद्ध (1739 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'हल्दीघाटी युद्ध (1576 ई.)' का सही संबंध 'महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)' से है (न कि 'बाबर बनाम राणा सांगा (मेवाड़)' से)। 18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. पेशवाओं का उत्कर्ष एवं पानीपत का तृतीय युद्ध (1761)   B. अटाला मस्जिद (जौनपुर)\nC. गुरु अंगद देव (दूसरे गुरु)   D. स्वतंत्र बंगाल सूबा\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["गुरु अंगद देव (दूसरे गुरु)","पेशवाओं का उत्कर्ष एवं पानीपत का तृतीय युद्ध (1761)","अटाला मस्जिद (जौनपुर)","स्वतंत्र बंगाल सूबा"],"correct":2,"explanation":"अटाला मस्जिद (जौनपुर) (1408 ई.), गुरु अंगद देव (दूसरे गुरु) (1539-1552 ई.), स्वतंत्र बंगाल सूबा (1717 ई.), पेशवाओं का उत्कर्ष एवं पानीपत का तृतीय युद्ध (1761) (1761 ई.)। अतः सर्वप्रथम अटाला मस्जिद (जौनपुर)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सिकंदर लोदी का मकबरा (1517)   B. मुहम्मद गोरी: तराइन का प्रथम, द्वितीय व चंदावर युद्ध\nC. खानवा युद्ध (1527 ई.)   D. विशिष्टाद्वैतवाद\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["विशिष्टाद्वैतवाद","सिकंदर लोदी का मकबरा (1517)","मुहम्मद गोरी: तराइन का प्रथम, द्वितीय व चंदावर युद्ध","खानवा युद्ध (1527 ई.)"],"correct":3,"explanation":"विशिष्टाद्वैतवाद (11वीं सदी ई.), मुहम्मद गोरी: तराइन का प्रथम, द्वितीय व चंदावर युद्ध (1192 ई.), सिकंदर लोदी का मकबरा (1517) (1517 ई.), खानवा युद्ध (1527 ई.) (1527 ई.)। अतः सबसे अंत में खानवा युद्ध (1527 ई.)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. अकबर ने जजिया कर अपने शासन के अंतिम वर्ष 1601 ई. में असीरगढ़ विजय के बाद पहली बार लगाया था।\n2. 18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।\n3. दक्कनी सल्तनत व राजवंश के अंतर्गत 'अहमदनगर (निजामशाही, 1490)' का ऐतिहासिक संबंध 'फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद' से था।\n4. सूफी सिलसिले एवं शब्दावली के अंतर्गत 'शेख अहमद सरहिन्दी' का ऐतिहासिक संबंध 'शेख बहाउद्दीन जकरिया (मुल्तान)' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. स्वतंत्र बंगाल सूबा   B. शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध\nC. सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)   D. हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["स्वतंत्र बंगाल सूबा","सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)","हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)","शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध"],"correct":2,"explanation":"हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार) (1540-1545 ई.), शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध (1628-1658 ई.), सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699) (1699 ई.), स्वतंत्र बंगाल सूबा (1717 ई.)। अतः सर्वप्रथम हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: अलाउद्दीन खिलजी ने राजस्व संग्रहकर्ताओं से बकाया वसूलने हेतु दीवान-ए-मुस्तखराज बनाया।\nकथन-2: विजयनगर साम्राज्य में 'अठवणे' (Athavane) केंद्रीय राजस्व विभाग था तथा कृष्णदेवराय ने विवाह कर समाप्त करके सामाजिक राहत दी (किंतु अन्य कर वेश्यालय व व्यापार आदि पर लागू थे)।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) अलाउद्दीन खिलजी ने राजस्व संग्रहकर्ताओं से बकाया वसूलने हेतु दीवान-ए-मुस्तखराज बनाया। (2) विजयनगर साम्राज्य में 'अठवणे' (Athavane) केंद्रीय राजस्व विभाग था तथा कृष्णदेवराय ने विवाह कर समाप्त करके सामाजिक राहत दी (किंतु अन्य कर वेश्यालय व व्यापार आदि पर लागू थे)।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. हुमायूँनामा   2. उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण\n3. छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान   4. अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार","options":["हुमायूँनामा → अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार → छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान → उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण","अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार → हुमायूँनामा → उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण → छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान","अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार → छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान → हुमायूँनामा → उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण","अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार → हुमायूँनामा → छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान → उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण"],"correct":3,"explanation":"सही कालानुक्रम: अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार (1296-1316 ई.), हुमायूँनामा (16वीं सदी ई.), छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान (1674 ई.), उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण (1739 ई.)"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें   B. अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान\nC. हल्दीघाटी युद्ध (1576 ई.)   D. तैमूर आक्रमण (1398), सैय्यद वंश एवं लोदी राजवंश\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["हल्दीघाटी युद्ध (1576 ई.)","अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान","बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें","तैमूर आक्रमण (1398), सैय्यद वंश एवं लोदी राजवंश"],"correct":0,"explanation":"बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें (1347 ई.), तैमूर आक्रमण (1398), सैय्यद वंश एवं लोदी राजवंश (1504 ई.), अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान (1556-1605 ई.), हल्दीघाटी युद्ध (1576 ई.) (1576 ई.)। अतः सबसे अंत में हल्दीघाटी युद्ध (1576 ई.)।"},
  {"q":"अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान — इसके संबंध में 'राजनीतिक विस्तार' कौन/क्या था?","options":["चौसा (1539) व कन्नौज/बिलग्राम (1540) में शेरशाह द्वारा हुमायूँ पराजित; सरहिंद युद्ध (1555 — हुमायूँ की वापसी); शेरशाह के 'रुपया' (178 ग्रेन चाँदी) व 'दाम' (ताँबा)","पानीपत II (1556 — हेमू पराजित); दास प्रथा अंत (1562), तीर्थयात्रा कर अंत (1563), जजिया अंत (1564); हल्दीघाटी (1576 — महाराणा प्रताप बनाम मानसिंह-आसफ खाँ)","'जंजीर-ए-अदल' (यमुना तट तक); गुरु अर्जुन देव को मृत्युदंड (खुसरो सहायता पर); कैप्टन विलियम हॉकिन्स (1608) व सर थॉमस रो (1615) का आगमन; दु-अस्पा सिह-अस्पा प्रथा","पानीपत I (1526 — इब्राहिम लोदी, तुलुगमा व उस्ताद अली/मुस्तफा तोपखाना); खानवा (1527 — राणा सांगा, जिहाद व तमगा समाप्ति); चंदेरी (1528 — मेदिनीराय); घाघरा (1529 — महमूद लोदी)"],"correct":1,"explanation":"गुजरात अभियान के दौरान अकबर ने सर्वप्रथम पुर्तगालियों से भेंट की तथा समुद्र देखा। 1560-62 के दौर को 'पेटीकोट शासन' (महाम अनगा प्रभाव) भी कहा जाता है।"},
  {"q":"ऐतिहासिक संदर्भ में 'चौसा (1539) व कन्नौज/बिलग्राम (1540) में शेरशाह द्वारा हुमायूँ पराजित; सरहिंद युद्ध (1555 — हुमायूँ की वापसी); शेरशाह के 'रुपया' (178 ग्रेन चाँदी) व 'दाम' (ताँबा)' (सत्ता संघर्ष व सुधार) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)","जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा","अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान","हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)"],"correct":3,"explanation":"हुमायूँ की जीवनी 'हुमायूँनामा' उसकी सौतेली बहन गुलबदन बेगम ने लिखी थी। 1556 ई. में दिल्ली के 'दीनपनाह' पुस्तकालय ('शेर मंडल') की सीढ़ियों से गिरकर हुमायूँ की मृत्यु हुई।"},
  {"q":"[PSC/CDS युग्म पहचान — मुगलकालीन प्रमुख युद्ध] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. हल्दीघाटी युद्ध (1576 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\n2. चौसा का युद्ध (1539 ई.) : औरंगजेब व मुराद बनाम दारा शिकोह\n3. सामूगढ़ का युद्ध (1658 ई.) : बाबर बनाम राणा सांगा (मेवाड़)\n4. खानवा युद्ध (1527 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: 18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया। (अन्य सही युग्म: चौसा का युद्ध (1539 ई.)→शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय, सामूगढ़ का युद्ध (1658 ई.)→औरंगजेब व मुराद बनाम दारा शिकोह, खानवा युद्ध (1527 ई.)→बाबर बनाम राणा सांगा (मेवाड़))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1556 ई. में बैरम खाँ के संरक्षण में अकबर ने पानीपत के द्वितीय युद्ध में आदिल शाह सूर के हिंदू सेनापति हेमू ('विक्रमादित्य') को हराकर मुगल सत्ता पुनः स्थापित की।\nकथन-2: अल-बरूनी ने 11वीं सदी में भारत की विद्या, धर्म, विज्ञान व समाज पर 'किताब-उल-हिन्द' लिखी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) 1556 ई. में बैरम खाँ के संरक्षण में अकबर ने पानीपत के द्वितीय युद्ध में आदिल शाह सूर के हिंदू सेनापति हेमू ('विक्रमादित्य') को हराकर मुगल सत्ता पुनः स्थापित की। (2) अल-बरूनी ने 11वीं सदी में भारत की विद्या, धर्म, विज्ञान व समाज पर 'किताब-उल-हिन्द' लिखी।"},
  {"q":"[UPSC/PCS सूची सुमेलन — मध्यकालीन स्थापत्य एवं निर्माता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. अटाला मस्जिद (जौनपुर)   |   1. नूरजहाँ (जहाँगीर काल, 1626)\nB. सासाराम झील मकबरा   |   2. इब्राहिम शाह शर्की ('पूर्व का सिराज')\nC. एत्मादुद्दौला का मकबरा (आगरा)   |   3. भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\nD. सिकंदर लोदी का मकबरा (1517)   |   4. शेरशाह सूरी","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1"],"correct":1,"explanation":"सही सुमेलन: अटाला मस्जिद (जौनपुर) (इब्राहिम शाह शर्की ('पूर्व का सिराज')), सासाराम झील मकबरा (शेरशाह सूरी), एत्मादुद्दौला का मकबरा (आगरा) (नूरजहाँ (जहाँगीर काल, 1626)), सिकंदर लोदी का मकबरा (1517) (भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन))।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. सामूगढ़ का युद्ध (1658 ई.) : औरंगजेब व मुराद बनाम दारा शिकोह\n2. हल्दीघाटी युद्ध (1576 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\n3. करनाल का युद्ध (1739 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\n4. चौसा का युद्ध (1539 ई.) : बाबर बनाम राणा सांगा (मेवाड़)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'चौसा का युद्ध (1539 ई.)' का सही संबंध 'शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय' से है (न कि 'बाबर बनाम राणा सांगा (मेवाड़)' से)। बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।"},
  {"q":"गुजरात के जौनपुर में शर्की सुल्तानों द्वारा निर्मित बिना मीनार वाली प्रसिद्ध मस्जिद कौन-सी है?","options":["इब्राहिम शाह शर्की ('पूर्व का सिराज')","अलाउद्दीन खिलजी","भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)","ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा"],"correct":0,"explanation":"1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है। जौनपुर में मध्यकाल में 'सिराज-ए-हिन्द' कहा जाने वाला शिक्षा केंद्र विकसित हुआ।"},
  {"q":"बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529) — इसके संबंध में 'युद्ध क्रम व रणनीति' कौन/क्या था?","options":["पानीपत II (1556 — हेमू पराजित); दास प्रथा अंत (1562), तीर्थयात्रा कर अंत (1563), जजिया अंत (1564); हल्दीघाटी (1576 — महाराणा प्रताप बनाम मानसिंह-आसफ खाँ)","'जंजीर-ए-अदल' (यमुना तट तक); गुरु अर्जुन देव को मृत्युदंड (खुसरो सहायता पर); कैप्टन विलियम हॉकिन्स (1608) व सर थॉमस रो (1615) का आगमन; दु-अस्पा सिह-अस्पा प्रथा","पानीपत I (1526 — इब्राहिम लोदी, तुलुगमा व उस्ताद अली/मुस्तफा तोपखाना); खानवा (1527 — राणा सांगा, जिहाद व तमगा समाप्ति); चंदेरी (1528 — मेदिनीराय); घाघरा (1529 — महमूद लोदी)","चौसा (1539) व कन्नौज/बिलग्राम (1540) में शेरशाह द्वारा हुमायूँ पराजित; सरहिंद युद्ध (1555 — हुमायूँ की वापसी); शेरशाह के 'रुपया' (178 ग्रेन चाँदी) व 'दाम' (ताँबा)"],"correct":2,"explanation":"बाबर ने भारत में काबुल से चारबाग (ज्यामितीय उद्यान) शैली प्रारंभ की। प्रारंभ में आगरा में दफनाने के बाद उसकी इच्छानुसार काबुल में मकबरा बना।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)   B. गुरु तेग बहादुर (नौवें गुरु)\nC. अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री   D. शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री","बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)","गुरु तेग बहादुर (नौवें गुरु)","शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध"],"correct":1,"explanation":"बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529) (1526 ई.), अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री (1565 ई.), शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध (1628-1658 ई.), गुरु तेग बहादुर (नौवें गुरु) (1675 ई.)। अतः सर्वप्रथम बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. खानवा युद्ध (1527 ई.)   B. संगोला की संधि (1750 ई.)\nC. गुरु हरगोबिंद (छठे गुरु)   D. शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["गुरु हरगोबिंद (छठे गुरु)","संगोला की संधि (1750 ई.)","शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध","खानवा युद्ध (1527 ई.)"],"correct":3,"explanation":"खानवा युद्ध (1527 ई.) (1527 ई.), गुरु हरगोबिंद (छठे गुरु) (1606-1644 ई.), शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध (1628-1658 ई.), संगोला की संधि (1750 ई.) (1750 ई.)। अतः सर्वप्रथम खानवा युद्ध (1527 ई.)।"},
  {"q":"[PSC/CDS युग्म पहचान — मुगलकालीन प्रमुख युद्ध] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. चौसा का युद्ध (1539 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\n2. हल्दीघाटी युद्ध (1576 ई.) : औरंगजेब व मुराद बनाम दारा शिकोह\n3. खानवा युद्ध (1527 ई.) : बाबर बनाम राणा सांगा (मेवाड़)\n4. सामूगढ़ का युद्ध (1658 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया। (अन्य सही युग्म: चौसा का युद्ध (1539 ई.)→शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय, हल्दीघाटी युद्ध (1576 ई.)→महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ), सामूगढ़ का युद्ध (1658 ई.)→औरंगजेब व मुराद बनाम दारा शिकोह)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. दारा शिकोह ने समूचे सिख 'आदि ग्रंथ' का तुर्की भाषा में 'मज्म-उल-बहरीन' नाम से अनुवाद कर औरंगजेब को भेंट किया।\n2. 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।\n3. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'हल्दीघाटी युद्ध (1576 ई.)' का ऐतिहासिक संबंध 'औरंगजेब व मुराद बनाम दारा शिकोह' से था।\n4. ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'चौसा का युद्ध (1539 ई.)' का ऐतिहासिक संबंध 'अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC Prelims पैटर्न — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों पर विचार कीजिए:\n1. हल्दीघाटी युद्ध (1576 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n2. चौसा का युद्ध (1539 ई.) : बाबर बनाम राणा सांगा (मेवाड़)\n3. खानवा युद्ध (1527 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: हल्दीघाटी युद्ध (1576 ई.) — महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ))। युग्म 2 गलत (सही: चौसा का युद्ध (1539 ई.) — शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय)। युग्म 3 गलत (सही: खानवा युद्ध (1527 ई.) — बाबर बनाम राणा सांगा (मेवाड़))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. अलाउद्दीन खिलजी प्रथम सुल्तान था जिसने भूमि की वास्तविक माप (मसाहत) कराकर उपज का 50% भू-राजस्व तय किया तथा बिचौलियों (खुत, मुकद्दम, चौधरी) के विशेषाधिकार छीने।\n2. केरल के कालड़ी में जन्मे शंकराचार्य ने चार मठों (ज्योतिर्मठ, शारदा, गोवर्धन, शृंगेरी) की स्थापना की।\n3. बाबर ने अपनी आत्मकथा 'बाबरनामा' फारसी भाषा में दिल्ली के आरामबाग में बैठकर लिखी थी।\n4. डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: बाबर ने 'तुजुक-ए-बाबरी' अपनी मातृभाषा चगताई तुर्की में लिखी थी, जिसका फारसी अनुवाद बाद में अकबर के समय अब्दुर्रहीम खानखाना ने किया।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ   2. एत्मादुद्दौला का मकबरा (आगरा)\n3. गुरु अंगद देव (दूसरे गुरु)   4. बीबी का मकबरा (औरंगाबाद)","options":["फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ → गुरु अंगद देव (दूसरे गुरु) → एत्मादुद्दौला का मकबरा (आगरा) → बीबी का मकबरा (औरंगाबाद)","गुरु अंगद देव (दूसरे गुरु) → फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ → एत्मादुद्दौला का मकबरा (आगरा) → बीबी का मकबरा (औरंगाबाद)","फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ → गुरु अंगद देव (दूसरे गुरु) → बीबी का मकबरा (औरंगाबाद) → एत्मादुद्दौला का मकबरा (आगरा)","फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ → एत्मादुद्दौला का मकबरा (आगरा) → गुरु अंगद देव (दूसरे गुरु) → बीबी का मकबरा (औरंगाबाद)"],"correct":0,"explanation":"सही कालानुक्रम: फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ (1351-1388 ई.), गुरु अंगद देव (दूसरे गुरु) (1539-1552 ई.), एत्मादुद्दौला का मकबरा (आगरा) (1626 ई.), बीबी का मकबरा (औरंगाबाद) (1660 ई.)"},
  {"q":"हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार) — इसके संबंध में 'सत्ता संघर्ष व सुधार' कौन/क्या था?","options":["चौसा (1539) व कन्नौज/बिलग्राम (1540) में शेरशाह द्वारा हुमायूँ पराजित; सरहिंद युद्ध (1555 — हुमायूँ की वापसी); शेरशाह के 'रुपया' (178 ग्रेन चाँदी) व 'दाम' (ताँबा)","'जंजीर-ए-अदल' (यमुना तट तक); गुरु अर्जुन देव को मृत्युदंड (खुसरो सहायता पर); कैप्टन विलियम हॉकिन्स (1608) व सर थॉमस रो (1615) का आगमन; दु-अस्पा सिह-अस्पा प्रथा","पानीपत I (1526 — इब्राहिम लोदी, तुलुगमा व उस्ताद अली/मुस्तफा तोपखाना); खानवा (1527 — राणा सांगा, जिहाद व तमगा समाप्ति); चंदेरी (1528 — मेदिनीराय); घाघरा (1529 — महमूद लोदी)","पानीपत II (1556 — हेमू पराजित); दास प्रथा अंत (1562), तीर्थयात्रा कर अंत (1563), जजिया अंत (1564); हल्दीघाटी (1576 — महाराणा प्रताप बनाम मानसिंह-आसफ खाँ)"],"correct":0,"explanation":"हुमायूँ की जीवनी 'हुमायूँनामा' उसकी सौतेली बहन गुलबदन बेगम ने लिखी थी। 1556 ई. में दिल्ली के 'दीनपनाह' पुस्तकालय ('शेर मंडल') की सीढ़ियों से गिरकर हुमायूँ की मृत्यु हुई।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. द्वैतवाद   B. सासाराम झील मकबरा\nC. मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ   D. चोल स्थानीय स्वशासन एवं उत्तरमेरूर अभिलेख\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ","सासाराम झील मकबरा","चोल स्थानीय स्वशासन एवं उत्तरमेरूर अभिलेख","द्वैतवाद"],"correct":1,"explanation":"चोल स्थानीय स्वशासन एवं उत्तरमेरूर अभिलेख (919-921 ई.), द्वैतवाद (13वीं सदी ई.), मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ (1325-1351 ई.), सासाराम झील मकबरा (1545 ई.)। अतः सबसे अंत में सासाराम झील मकबरा।"},
  {"q":"[UPSC/PCS सूची सुमेलन — मध्यकालीन स्थापत्य एवं निर्माता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. सासाराम झील मकबरा   |   1. भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\nB. गयासुद्दीन तुगलक मकबरा   |   2. शेरशाह सूरी\nC. सिकंदर लोदी का मकबरा (1517)   |   3. इब्राहिम शाह शर्की ('पूर्व का सिराज')\nD. अटाला मस्जिद (जौनपुर)   |   4. ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा","options":["A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"correct":2,"explanation":"सही सुमेलन: सासाराम झील मकबरा (शेरशाह सूरी), गयासुद्दीन तुगलक मकबरा (ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा), सिकंदर लोदी का मकबरा (1517) (भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)), अटाला मस्जिद (जौनपुर) (इब्राहिम शाह शर्की ('पूर्व का सिराज'))।"},
  {"q":"अकबर की राजपूत नीति, नवरत्न व मनसबदारी के नियम — इसके संबंध में 'प्रमुख नीतियाँ' कौन/क्या था?","options":["वजीर/दीवान (वित्त), मीर बख्शी (सैन्य विभाग व मनसब वेतन पत्र 'सरखत'), मीर सामां (शाही कारखाने व रसोई), काजी-उल-कुजात (न्याय)","हुमायूँ का मकबरा (दिल्ली), आगरा किला (अकबर), फतेहपुर सीकरी (बुलंद दरवाजा, पंचमहल, इबादतखाना, सलीम चिश्ती मकबरा), सिकंदरा (अकबर मकबरा — बिना गुंबद), ताजमहल","टोडरमल द्वारा 'आइन-ए-दहसाला' (1580 — 10 वर्षों का औसत); 'मनसबदारी' (मंगोल दशमलव आधारित जात व सवार रैंक); इबादतखाना (1575), महजरनामा (1579), दीन-ए-इलाही (1582)","सुलेह-ए-कुल पर आधारित मित्रता (आमेर के भारमल प्रथम राजपूत संधि 1562, भगवानदास-मानसिंह को उच्च मनसब); मेवाड़ (प्रताप), रणथंभौर, कालिंजर; 'जाट-सवार' रैंक प्रणाली"],"correct":3,"explanation":"जहाँगीर ने बिना 'जात' बढ़ाए घुड़सवार बढ़ाने हेतु 'दु-अस्पा सिह-अस्पा' प्रणाली शुरू की, जबकि शाहजहाँ ने वास्तविक सैनिक खर्च व आय के अंतर पर 'माहवार' (महीनावार) अनुपात लागू किया।"},
  {"q":"दिल्ली स्थित 'पुराना किला' एवं 'शेरशाह का अष्टकोणीय मकबरा (सासाराम)' किसने बनवाया?","options":["शेरशाह सूरी","ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा","भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)","अलाउद्दीन खिलजी"],"correct":0,"explanation":"बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है। शेरशाह ने दिल्ली के पुराना किला के भीतर 'किला-ए-कुहना' मस्जिद भी बनवाई।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।\n2. शाहजहाँ ने बलख-बदख्शां का मध्य एशिया अभियान किया, पुर्तगालियों को 1632 में हुगली से खदेड़ा और अहमदनगर (1633) को पूरी तरह मुगल साम्राज्य में मिलाया।\n3. मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'सासाराम झील मकबरा' का ऐतिहासिक संबंध 'नूरजहाँ (जहाँगीर काल, 1626)' से था।\n4. 18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: 'सासाराम झील मकबरा' का सही संबंध 'शेरशाह सूरी' से था — बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: टीपू सुल्तान ने श्रीरंगपट्टनम में फ्रांस के सम्मान में 'स्वतंत्रता का वृक्ष' लगाया, स्वयं को 'नागरिक टीपू' कहा और आधुनिक नौसेना बोर्ड व रेशम उत्पादन को बढ़ावा दिया।\nकथन-2: बलबन ने सुल्तान को पृथ्वी पर ईश्वर का प्रतिनिधि ('नियाबत-ए-खुदाई') व 'जिल्ल-ए-इलाही' घोषित कर ईरानी दरबारी शिष्टाचार 'सिजदा व पैबोस' लागू किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) टीपू सुल्तान ने श्रीरंगपट्टनम में फ्रांस के सम्मान में 'स्वतंत्रता का वृक्ष' लगाया, स्वयं को 'नागरिक टीपू' कहा और आधुनिक नौसेना बोर्ड व रेशम उत्पादन को बढ़ावा दिया। (2) बलबन ने सुल्तान को पृथ्वी पर ईश्वर का प्रतिनिधि ('नियाबत-ए-खुदाई') व 'जिल्ल-ए-इलाही' घोषित कर ईरानी दरबारी शिष्टाचार 'सिजदा व पैबोस' लागू किया।"},
  {"q":"[PSC/CDS युग्म पहचान — मुगलकालीन प्रमुख युद्ध] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. सामूगढ़ का युद्ध (1658 ई.) : बाबर बनाम राणा सांगा (मेवाड़)\n2. खानवा युद्ध (1527 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\n3. हल्दीघाटी युद्ध (1576 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\n4. चौसा का युद्ध (1539 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई। (अन्य सही युग्म: सामूगढ़ का युद्ध (1658 ई.)→औरंगजेब व मुराद बनाम दारा शिकोह, खानवा युद्ध (1527 ई.)→बाबर बनाम राणा सांगा (मेवाड़), हल्दीघाटी युद्ध (1576 ई.)→महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-विजारत' का ऐतिहासिक संबंध 'सैन्य विभाग (स्थापना: बलबन)' से था।\n2. बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।\n3. मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'एत्मादुद्दौला का मकबरा (आगरा)' का ऐतिहासिक संबंध 'औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)' से था।\n4. सूफी सिलसिले एवं शब्दावली के अंतर्गत 'सुहरावर्दी सिलसिला (भारत)' का ऐतिहासिक संबंध 'नक्शबंदी सिलसिला ('वहदत-उल-शुहूद' सिद्धांत)' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1556 ई. में बैरम खाँ के संरक्षण में अकबर ने पानीपत के द्वितीय युद्ध में आदिल शाह सूर के हिंदू सेनापति हेमू ('विक्रमादित्य') को हराकर मुगल सत्ता पुनः स्थापित की।\nकथन-2: मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'अटाला मस्जिद (जौनपुर)' का ऐतिहासिक संबंध 'अलाउद्दीन खिलजी' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (1556 ई. में बैरम खाँ के संरक्षण में अकबर ने पानीपत के द्वितीय युद्ध में आदिल शाह सूर के हिंदू सेनापति हेमू ('विक्रमादित्य') को हराकर मुगल सत्ता पुनः स्थापित की।)। कथन-2 गलत है — 'अटाला मस्जिद (जौनपुर)' का सही संबंध 'इब्राहिम शाह शर्की ('पूर्व का सिराज')' से था — 1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'अलाई दरवाजा (1311 ई.)' का ऐतिहासिक संबंध 'ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा' से था।\nकथन-2: मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'तबकात-ए-नासिरी' का ऐतिहासिक संबंध 'जियाउद्दीन बरनी' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'अलाई दरवाजा (1311 ई.)' का सही संबंध 'अलाउद्दीन खिलजी' से था — अलाउद्दीन खिलजी ने कुव्वत-उल-इस्लाम मस्जिद के प्रवेश द्वार के रूप में अलाई दरवाजा बनवाया। (2) 'तबकात-ए-नासिरी' का सही संबंध 'मिनहाज-उस-सिराज' से था — सुल्तान नासिरुद्दीन महमूद के काल में मुख्य काजी मिनहाज-उस-सिराज ने फारसी में यह ग्रंथ लिखा।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'सासाराम झील मकबरा' का ऐतिहासिक संबंध 'नूरजहाँ (जहाँगीर काल, 1626)' से था।\nकथन-2: रामानंद ने भक्ति के द्वार सभी जातियों व स्त्रियों के लिए खोले; उनके शिष्यों में कबीर (जुलाहा), रैदास (चर्मकार), धन्ना (जाट), सेन (नाई) व पीपा शामिल थे।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('सासाराम झील मकबरा' का सही संबंध 'शेरशाह सूरी' से था — बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है।)। कथन-2 सत्य है (रामानंद ने भक्ति के द्वार सभी जातियों व स्त्रियों के लिए खोले; उनके शिष्यों में कबीर (जुलाहा), रैदास (चर्मकार), धन्ना (जाट), सेन (नाई) व पीपा शामिल थे।)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'पानीपत का तृतीय युद्ध (1761 ई.)' का ऐतिहासिक संबंध 'नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया' से था।\n2. भक्ति आंदोलन का एकमात्र उद्देश्य संस्कृत व्याकरण के प्राचीन कर्मकांडी यज्ञों को पुनर्जीवित कर शूद्रों व महिलाओं को मठों से बाहर करना था।\n3. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'सामूगढ़ का युद्ध (1658 ई.)' का ऐतिहासिक संबंध 'नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'' से था।\n4. 1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"'बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)' के ऐतिहासिक संदर्भ में 'साहित्य व बागवानी' निम्नलिखित में से क्या है?","options":["तुर्की भाषा में आत्मकथा 'तुजुक-ए-बाबरी' (बाबरनामा) व 'मुबइयान' पद्य शैली; चारबाग शैली की शुरुआत","राजपूतों के साथ वैवाहिक-मित्रता नीति; गुजरात विजय (1572-73 — बुलंद दरवाजा, समुद्र दर्शन); असीरगढ़ (1601 — अंतिम विजय)","नूरजहाँ द्वारा पित्रादुरा (Pietra Dura) युक्त एत्मादुद्दौला मकबरा (पूर्णतः संगमरमर की प्रथम मुगल इमारत); उस्ताद मंसूर (पक्षी) व अबुल हसन चित्रकार","'पट्टा व कबूलियत', 'जरीबाना' व 'मुहसिलाना' कर, सड़क-ए-आजम (ग्रैंड ट्रंक रोड) व 1700 सरायें, सासाराम (बिहार) में अष्टकोणीय मकबरा"],"correct":0,"explanation":"बाबर ने भारत में काबुल से चारबाग (ज्यामितीय उद्यान) शैली प्रारंभ की। प्रारंभ में आगरा में दफनाने के बाद उसकी इच्छानुसार काबुल में मकबरा बना।"},
  {"q":"[UPSC Prelims PYQ] 'योग कलंदर' (Amritakunda अनुवाद सहित) तथा सूफी चिश्ती संतों द्वारा अपनाए गए प्राणायाम जैसे हठयोग अभ्यास किस विचार परंपरा को दर्शाते हैं?","options":["अकबर द्वारा लागू किया गया राजनीतिक सैन्य नियम","मध्यकालीन भारत में नाथपंथी योगियों और सूफी संतों के बीच सांस्कृतिक-आध्यात्मिक समन्वय","दक्षिण भारत का पल्लव वास्तुशास्त्र","पेशवा कालीन मराठी कराधान व्यवस्था"],"correct":1,"explanation":"बाबा फरीद व निजामुद्दीन औलिया जैसे चिश्ती सूफी संतों और नाथपंथियों के बीच योग व श्वास-नियंत्रण ('पास-ए-अनफास') का गहरा आदान-प्रदान हुआ।"},
  {"q":"1539 ई. के 'चौसा के युद्ध' में किस अफगान शासक ने हुमायूँ को पराजित किया?","options":["बाबर बनाम राणा सांगा (मेवाड़)","महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)","शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय","औरंगजेब व मुराद बनाम दारा शिकोह"],"correct":2,"explanation":"बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई। इसके बाद शेर खाँ ने 'शेरशाह' की उपाधि ग्रहण की।"},
  {"q":"1576 ई. का ऐतिहासिक 'हल्दीघाटी का युद्ध' किन पक्षों के मध्य लड़ा गया?","options":["महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)","बाबर बनाम राणा सांगा (मेवाड़)","शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय","औरंगजेब व मुराद बनाम दारा शिकोह"],"correct":0,"explanation":"18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया। प्रताप ने आजीवन अकबर की अधीनता स्वीकार नहीं की।"},
  {"q":"[UPSC/PCS सूची सुमेलन — मुगलकालीन प्रमुख युद्ध] सूची-I को सूची-II से सुमेलित कीजिए:\nA. खानवा युद्ध (1527 ई.)   |   1. शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\nB. हल्दीघाटी युद्ध (1576 ई.)   |   2. बाबर बनाम राणा सांगा (मेवाड़)\nC. चौसा का युद्ध (1539 ई.)   |   3. नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\nD. करनाल का युद्ध (1739 ई.)   |   4. महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)","options":["A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3"],"correct":3,"explanation":"सही सुमेलन: खानवा युद्ध (1527 ई.) (बाबर बनाम राणा सांगा (मेवाड़)), हल्दीघाटी युद्ध (1576 ई.) (महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)), चौसा का युद्ध (1539 ई.) (शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय), करनाल का युद्ध (1739 ई.) (नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला')।"},
  {"q":"[UPSC/PCS सूची सुमेलन — मुगलकालीन प्रमुख युद्ध] सूची-I को सूची-II से सुमेलित कीजिए:\nA. खानवा युद्ध (1527 ई.)   |   1. नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\nB. करनाल का युद्ध (1739 ई.)   |   2. महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\nC. चौसा का युद्ध (1539 ई.)   |   3. बाबर बनाम राणा सांगा (मेवाड़)\nD. हल्दीघाटी युद्ध (1576 ई.)   |   4. शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: खानवा युद्ध (1527 ई.) (बाबर बनाम राणा सांगा (मेवाड़)), करनाल का युद्ध (1739 ई.) (नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'), चौसा का युद्ध (1539 ई.) (शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय), हल्दीघाटी युद्ध (1576 ई.) (महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बाबर ने अपनी आत्मकथा 'बाबरनामा' फारसी भाषा में दिल्ली के आरामबाग में बैठकर लिखी थी।\nकथन-2: बलबन ने मंगोल संकट से निपटने हेतु केंद्रीय सैन्य विभाग 'दीवान-ए-अर्ज' स्थापित किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (बाबर ने 'तुजुक-ए-बाबरी' अपनी मातृभाषा चगताई तुर्की में लिखी थी, जिसका फारसी अनुवाद बाद में अकबर के समय अब्दुर्रहीम खानखाना ने किया।)। कथन-2 सत्य है (बलबन ने मंगोल संकट से निपटने हेतु केंद्रीय सैन्य विभाग 'दीवान-ए-अर्ज' स्थापित किया।)।"},
  {"q":"'अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान' के ऐतिहासिक संदर्भ में 'प्रमुख किले व नीति' निम्नलिखित में से क्या है?","options":["नूरजहाँ द्वारा पित्रादुरा (Pietra Dura) युक्त एत्मादुद्दौला मकबरा (पूर्णतः संगमरमर की प्रथम मुगल इमारत); उस्ताद मंसूर (पक्षी) व अबुल हसन चित्रकार","तुर्की भाषा में आत्मकथा 'तुजुक-ए-बाबरी' (बाबरनामा) व 'मुबइयान' पद्य शैली; चारबाग शैली की शुरुआत","राजपूतों के साथ वैवाहिक-मित्रता नीति; गुजरात विजय (1572-73 — बुलंद दरवाजा, समुद्र दर्शन); असीरगढ़ (1601 — अंतिम विजय)","'पट्टा व कबूलियत', 'जरीबाना' व 'मुहसिलाना' कर, सड़क-ए-आजम (ग्रैंड ट्रंक रोड) व 1700 सरायें, सासाराम (बिहार) में अष्टकोणीय मकबरा"],"correct":2,"explanation":"गुजरात अभियान के दौरान अकबर ने सर्वप्रथम पुर्तगालियों से भेंट की तथा समुद्र देखा। 1560-62 के दौर को 'पेटीकोट शासन' (महाम अनगा प्रभाव) भी कहा जाता है।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: पानीपत के प्रथम युद्ध (21 अप्रैल 1526) में बाबर ने उज्बेकों से सीखी 'तुलुगमा' युद्ध पद्धति और उस्मानी विधि से तोपें सजाकर इब्राहिम लोदी की विशाल सेना को हराया।\nकथन-2: राजेंद्र प्रथम ने गंगा घाटी के अभियान में पाल शासक महिपाल प्रथम को पराजित कर 'गंगैकोण्डचोल' उपाधि व नवीन राजधानी बसाई।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) पानीपत के प्रथम युद्ध (21 अप्रैल 1526) में बाबर ने उज्बेकों से सीखी 'तुलुगमा' युद्ध पद्धति और उस्मानी विधि से तोपें सजाकर इब्राहिम लोदी की विशाल सेना को हराया। (2) राजेंद्र प्रथम ने गंगा घाटी के अभियान में पाल शासक महिपाल प्रथम को पराजित कर 'गंगैकोण्डचोल' उपाधि व नवीन राजधानी बसाई।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: हुमायूँ ने 1540 ई. के कन्नौज (बिलग्राम) युद्ध में शेरशाह सूरी को अंतिम रूप से हराकर ससाराम पर कब्जा कर लिया।\nकथन-2: मुगलकालीन प्रशासनिक शब्दावली के अंतर्गत 'मदद-ए-माअश (सयूरगल)' का ऐतिहासिक संबंध 'व्यापारिक साख व विनिमय पत्र (Bill of Exchange)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 1540 ई. के कन्नौज युद्ध में शेरशाह सूरी ने हुमायूँ को निर्णायक रूप से हराकर दिल्ली में द्वितीय अफगान (सूर) साम्राज्य की स्थापना की। (2) 'मदद-ए-माअश (सयूरगल)' का सही संबंध 'विद्वानों, संतों व धार्मिक संस्थानों को करमुक्त अनुदान भूमि' से था — सद्र-उस-सुदूर की संस्तुति पर विद्वानों व फकीरों को जीवनयापन हेतु दी गई राजस्व-मुक्त भूमि मदद-ए-माअश थी।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मुगलकालीन प्रमुख युद्ध के अंतर्गत 'हल्दीघाटी युद्ध (1576 ई.)' का ऐतिहासिक संबंध 'औरंगजेब व मुराद बनाम दारा शिकोह' से था।\nकथन-2: 1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('हल्दीघाटी युद्ध (1576 ई.)' का सही संबंध 'महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)' से था — 18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।)। कथन-2 सत्य है (1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।\nकथन-2: मुगलकालीन प्रमुख युद्ध के अंतर्गत 'करनाल का युद्ध (1739 ई.)' का ऐतिहासिक संबंध 'बाबर बनाम राणा सांगा (मेवाड़)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।)। कथन-2 गलत है — 'करनाल का युद्ध (1739 ई.)' का सही संबंध 'नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'' से था — फरवरी 1739 में करनाल युद्ध में मुगल सेना कुछ घंटों में परास्त हुई और दिल्ली में भयानक कत्लेआम हुआ।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. अकबर ने जजिया कर अपने शासन के अंतिम वर्ष 1601 ई. में असीरगढ़ विजय के बाद पहली बार लगाया था।\n2. मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए।\n3. सरहिन्दी ने जहाँगीर के काल में अकबर की उदार नीतियों और 'वहदत-उल-वुजूद' का कड़ा विरोध किया।\n4. मुहम्मद बिन तुगलक ने दोआब में खेती सुधारने हेतु 'दीवान-ए-अमीर कोही' बनाया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: अकबर ने 1564 ई. में गैर-मुसलमानों पर लगने वाले भेदभावपूर्ण 'जजिया' कर को पूर्णतः समाप्त कर दिया था।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. अटाला मस्जिद (जौनपुर) : इब्राहिम शाह शर्की ('पूर्व का सिराज')\n2. सिकंदर लोदी का मकबरा (1517) : भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\n3. बीबी का मकबरा (औरंगाबाद) : औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)\n4. सासाराम झील मकबरा : नूरजहाँ (जहाँगीर काल, 1626)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'सासाराम झील मकबरा' का सही संबंध 'शेरशाह सूरी' से है (न कि 'नूरजहाँ (जहाँगीर काल, 1626)' से)। बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण   B. हल्दीघाटी युद्ध (1576 ई.)\nC. किताब-उल-हिन्द   D. कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण","कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)","हल्दीघाटी युद्ध (1576 ई.)","किताब-उल-हिन्द"],"correct":2,"explanation":"अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण (1025 ई.), किताब-उल-हिन्द (11वीं सदी ई.), कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) (1211-1236 ई.), हल्दीघाटी युद्ध (1576 ई.) (1576 ई.)। अतः सबसे अंत में हल्दीघाटी युद्ध (1576 ई.)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मुगलकालीन प्रमुख युद्ध के अंतर्गत 'खानवा युद्ध (1527 ई.)' का ऐतिहासिक संबंध 'शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय' से था।\nकथन-2: तक्कोलम के युद्ध में राष्ट्रकूट राजा कृष्ण तृतीय ने चोलों को करारी हार दी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('खानवा युद्ध (1527 ई.)' का सही संबंध 'बाबर बनाम राणा सांगा (मेवाड़)' से था — 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।)। कथन-2 सत्य है (तक्कोलम के युद्ध में राष्ट्रकूट राजा कृष्ण तृतीय ने चोलों को करारी हार दी।)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. हल्दीघाटी युद्ध (1576 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\n2. खानवा युद्ध (1527 ई.) : औरंगजेब व मुराद बनाम दारा शिकोह\n3. चौसा का युद्ध (1539 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n4. करनाल का युद्ध (1739 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'खानवा युद्ध (1527 ई.)' का सही संबंध 'बाबर बनाम राणा सांगा (मेवाड़)' से है (न कि 'औरंगजेब व मुराद बनाम दारा शिकोह' से)। 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें   B. हल्दीघाटी युद्ध (1576 ई.)\nC. फर्नओ नूनिज (पुर्तगाल)   D. अफनासी निकितिन (रूस)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["हल्दीघाटी युद्ध (1576 ई.)","फर्नओ नूनिज (पुर्तगाल)","बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें","अफनासी निकितिन (रूस)"],"correct":0,"explanation":"बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें (1347 ई.), अफनासी निकितिन (रूस) (1470 ई.), फर्नओ नूनिज (पुर्तगाल) (1535 ई.), हल्दीघाटी युद्ध (1576 ई.) (1576 ई.)। अतः सबसे अंत में हल्दीघाटी युद्ध (1576 ई.)।"},
  {"q":"ऐतिहासिक संदर्भ में 'सुलेह-ए-कुल पर आधारित मित्रता (आमेर के भारमल प्रथम राजपूत संधि 1562, भगवानदास-मानसिंह को उच्च मनसब); मेवाड़ (प्रताप), रणथंभौर, कालिंजर; 'जाट-सवार' रैंक प्रणाली' (प्रमुख नीतियाँ) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["मुगलकालीन वास्तुकला के प्रमुख स्मारक एवं विशेषताएँ","मुगलकालीन केंद्रीय व प्रांतीय प्रशासन तथा राजस्व पद","अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल","अकबर की राजपूत नीति, नवरत्न व मनसबदारी के नियम"],"correct":3,"explanation":"जहाँगीर ने बिना 'जात' बढ़ाए घुड़सवार बढ़ाने हेतु 'दु-अस्पा सिह-अस्पा' प्रणाली शुरू की, जबकि शाहजहाँ ने वास्तविक सैनिक खर्च व आय के अंतर पर 'माहवार' (महीनावार) अनुपात लागू किया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. हुमायूँ ने 1540 ई. के कन्नौज (बिलग्राम) युद्ध में शेरशाह सूरी को अंतिम रूप से हराकर ससाराम पर कब्जा कर लिया।\n2. इल्तुतमिश ने अरबी शैली के शुद्ध सिक्के—चाँदी का 'टंका' (175 ग्रेन) और ताँबे का 'जीतल'—चलाए तथा 40 तुर्क अमीरों का 'तुर्कान-ए-चहलगानी' बनाया।\n3. नक्शबंदी सिलसिला सबसे कट्टरवादी सूफी धारा थी जिसके संत शेख अहमद सरहिन्दी ('मुजद्दिद अलिफ सानी') ने अकबर की उदार नीति व 'वहदत-उल-वुजूद' का विरोध कर 'वहदत-उल-शुहूद' दिया।\n4. दिल्ली सल्तनत में 'खालिसा' भूमि की आय सीधे शाही राजकोष में जाती थी और अलाउद्दीन खिलजी ने अनेक पुराने अनुदान ('इनाम', 'वक्फ', 'मिल्क') रद्द करके खालिसा भूमि का विस्तार किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 1540 ई. के कन्नौज युद्ध में शेरशाह सूरी ने हुमायूँ को निर्णायक रूप से हराकर दिल्ली में द्वितीय अफगान (सूर) साम्राज्य की स्थापना की।"},
  {"q":"[UPSC Prelims पैटर्न — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सासाराम झील मकबरा : शेरशाह सूरी\n2. एत्मादुद्दौला का मकबरा (आगरा) : भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\n3. सिकंदर लोदी का मकबरा (1517) : अलाउद्दीन खिलजी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है।) युग्म 2 गलत (सही: एत्मादुद्दौला का मकबरा (आगरा) — नूरजहाँ (जहाँगीर काल, 1626))। युग्म 3 गलत (सही: सिकंदर लोदी का मकबरा (1517) — भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन))।"},
  {"q":"ऐतिहासिक संदर्भ में 'पानीपत I (1526 — इब्राहिम लोदी, तुलुगमा व उस्ताद अली/मुस्तफा तोपखाना); खानवा (1527 — राणा सांगा, जिहाद व तमगा समाप्ति); चंदेरी (1528 — मेदिनीराय); घाघरा (1529 — महमूद लोदी)' (युद्ध क्रम व रणनीति) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा","हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)","बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)","अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान"],"correct":2,"explanation":"बाबर ने भारत में काबुल से चारबाग (ज्यामितीय उद्यान) शैली प्रारंभ की। प्रारंभ में आगरा में दफनाने के बाद उसकी इच्छानुसार काबुल में मकबरा बना।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. फतवा-ए-जहाँदारी   B. अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान\nC. बीजापुर (आदिलशाही, 1489)   D. सिकंदर लोदी का मकबरा (1517)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["बीजापुर (आदिलशाही, 1489)","सिकंदर लोदी का मकबरा (1517)","फतवा-ए-जहाँदारी","अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान"],"correct":3,"explanation":"फतवा-ए-जहाँदारी (14वीं सदी ई.), बीजापुर (आदिलशाही, 1489) (1489 ई.), सिकंदर लोदी का मकबरा (1517) (1517 ई.), अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान (1556-1605 ई.)। अतः सबसे अंत में अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: अकबर ने जजिया कर अपने शासन के अंतिम वर्ष 1601 ई. में असीरगढ़ विजय के बाद पहली बार लगाया था।\nकथन-2: नक्शबंदी सिलसिला सबसे कट्टरवादी सूफी धारा थी जिसके संत शेख अहमद सरहिन्दी ('मुजद्दिद अलिफ सानी') ने अकबर की उदार नीति व 'वहदत-उल-वुजूद' का विरोध कर 'वहदत-उल-शुहूद' दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (अकबर ने 1564 ई. में गैर-मुसलमानों पर लगने वाले भेदभावपूर्ण 'जजिया' कर को पूर्णतः समाप्त कर दिया था।)। कथन-2 सत्य है (नक्शबंदी सिलसिला सबसे कट्टरवादी सूफी धारा थी जिसके संत शेख अहमद सरहिन्दी ('मुजद्दिद अलिफ सानी') ने अकबर की उदार नीति व 'वहदत-उल-वुजूद' का विरोध कर 'वहदत-उल-शुहूद' दिया।)।"},
  {"q":"[UPSC Prelims पैटर्न — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों पर विचार कीजिए:\n1. खानवा युद्ध (1527 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\n2. करनाल का युद्ध (1739 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n3. चौसा का युद्ध (1539 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: खानवा युद्ध (1527 ई.) — बाबर बनाम राणा सांगा (मेवाड़))। युग्म 2 गलत (सही: करनाल का युद्ध (1739 ई.) — नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला')। युग्म 3 गलत (सही: चौसा का युद्ध (1539 ई.) — शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'पद्मावत (अवधी, 1540)' का ऐतिहासिक संबंध 'अब्दुर्रहीम खानखाना एवं रसखान (हिंदी-ब्रज काव्य)' से था।\nकथन-2: सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-मुस्तखराज' का ऐतिहासिक संबंध 'कृषि विभाग व तकावी ऋण वितरण (मुहम्मद बिन तुगलक)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'पद्मावत (अवधी, 1540)' का सही संबंध 'मलिक मुहम्मद जायसी' से था — शेरशाह सूरी के समकालीन सूफी कवि जायसी ने 1540 ई. में अवधी भाषा में पद्मावत लिखा। (2) 'दीवान-ए-मुस्तखराज' का सही संबंध 'बकाया राजस्व वसूली व भ्रष्ट अधिकारियों की जाँच (अलाउद्दीन)' से था — अलाउद्दीन खिलजी ने राजस्व संग्रहकर्ताओं से बकाया वसूलने हेतु दीवान-ए-मुस्तखराज बनाया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मुगलकालीन प्रशासनिक शब्दावली के अंतर्गत 'परती (Parauti)' का ऐतिहासिक संबंध 'विद्वानों, संतों व धार्मिक संस्थानों को करमुक्त अनुदान भूमि' से था।\n2. अकबर की मनसबदारी व्यवस्था वंशानुगत नहीं थी—मनसबदार की मृत्यु के बाद उसकी संपत्ति राजकोष ('जब्त') कर ली जाती थी ('एस्कीट' प्रणाली), हालांकि बाद में संतानों को नया मनसब मिल सकता था।\n3. कुतुबुद्दीन ऐबक ने दिल्ली को अपनी स्थायी राजधानी बनाया और बगदाद के खलीफा से सुल्तान की औपचारिक उपाधि व सनद प्राप्त की।\n4. कादिरी सूफी सिलसिला संगीत का कट्टर विरोधी था और इसने दारा शिकोह को सूफी रहस्यवाद की शिक्षा देने से मना कर दिया था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (अकबर की मनसबदारी व्यवस्था वंशानुगत नहीं थी—मनसबदार की मृत्यु के बाद उसकी संपत्ति राजकोष ('जब्त') कर ली जाती थी ('एस्कीट' प्रणाली), हालांकि बाद में संतानों को नया मनसब मिल सकता था।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'सासाराम झील मकबरा' का ऐतिहासिक संबंध 'नूरजहाँ (जहाँगीर काल, 1626)' से था।\nकथन-2: गुरु अर्जुन देव की शहादत के बाद छठे गुरु हरगोबिंद ने सिखों का सैन्यीकरण किया और अमृतसर की किलेबंदी की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('सासाराम झील मकबरा' का सही संबंध 'शेरशाह सूरी' से था — बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है।)। कथन-2 सत्य है (गुरु अर्जुन देव की शहादत के बाद छठे गुरु हरगोबिंद ने सिखों का सैन्यीकरण किया और अमृतसर की किलेबंदी की।)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. सिख गुरु परंपरा के अंतर्गत 'गुरु अंगद देव (दूसरे गुरु)' का ऐतिहासिक संबंध '22 गद्दियाँ (मंजी प्रथा) व 'आनंद कारज' विवाह गीत रचना' से था।\n2. भक्ति मत एवं प्रवर्तक के अंतर्गत 'विशिष्टाद्वैतवाद' का ऐतिहासिक संबंध 'माध्वाचार्य (13वीं सदी, उडुपी)' से था।\n3. मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'गयासुद्दीन तुगलक मकबरा' का ऐतिहासिक संबंध 'भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)' से था।\n4. शेरशाह सूरी ने मुगल अकबर के प्रशासनिक ढाँचे का अग्रदूत बनकर चाँदी का मानक 'रुपया' चलाया, जो ब्रिटिश काल तक भारतीय मुद्रा का आधार बना रहा।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (शेरशाह सूरी ने मुगल अकबर के प्रशासनिक ढाँचे का अग्रदूत बनकर चाँदी का मानक 'रुपया' चलाया, जो ब्रिटिश काल तक भारतीय मुद्रा का आधार बना रहा।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC Prelims पैटर्न — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चौसा का युद्ध (1539 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n2. करनाल का युद्ध (1739 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\n3. हल्दीघाटी युद्ध (1576 ई.) : औरंगजेब व मुराद बनाम दारा शिकोह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।) युग्म 2 सही (फरवरी 1739 में करनाल युद्ध में मुगल सेना कुछ घंटों में परास्त हुई और दिल्ली में भयानक कत्लेआम हुआ।) युग्म 3 गलत (सही: हल्दीघाटी युद्ध (1576 ई.) — महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मराठा अष्टप्रधान परिषद के अंतर्गत 'अमात्य (मजूमदार)' का ऐतिहासिक संबंध 'राजा के दैनिक कार्य, गृह व गुप्तचर मामलों का विवरण रखना' से था।\n2. 1556 ई. में बैरम खाँ के संरक्षण में अकबर ने पानीपत के द्वितीय युद्ध में आदिल शाह सूर के हिंदू सेनापति हेमू ('विक्रमादित्य') को हराकर मुगल सत्ता पुनः स्थापित की।\n3. विदेशी यात्री एवं शासक के अंतर्गत 'अफनासी निकितिन (रूस)' का ऐतिहासिक संबंध 'मुहम्मद बिन तुगलक (1333 ई.)' से था।\n4. सिख गुरु परंपरा के अंतर्गत 'गुरु रामदास (चौथे गुरु)' का ऐतिहासिक संबंध 'आदि ग्रंथ का संकलन (1604) एवं हरमंदिर साहिब निर्माण' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (1556 ई. में बैरम खाँ के संरक्षण में अकबर ने पानीपत के द्वितीय युद्ध में आदिल शाह सूर के हिंदू सेनापति हेमू ('विक्रमादित्य') को हराकर मुगल सत्ता पुनः स्थापित की।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।\nकथन-2: पानीपत के द्वितीय युद्ध में अकबर के संरक्षक बैरम खाँ ने हिंदू सम्राट हेमू को पराजित किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया। (2) पानीपत के द्वितीय युद्ध में अकबर के संरक्षक बैरम खाँ ने हिंदू सम्राट हेमू को पराजित किया।"},
  {"q":"[PSC/CDS युग्म पहचान — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अटाला मस्जिद (जौनपुर) : औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)\n2. सासाराम झील मकबरा : शेरशाह सूरी\n3. बीबी का मकबरा (औरंगाबाद) : अलाउद्दीन खिलजी\n4. अलाई दरवाजा (1311 ई.) : भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है। (अन्य सही युग्म: अटाला मस्जिद (जौनपुर)→इब्राहिम शाह शर्की ('पूर्व का सिराज'), बीबी का मकबरा (औरंगाबाद)→औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु), अलाई दरवाजा (1311 ई.)→अलाउद्दीन खिलजी)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।\n2. पानीपत के द्वितीय युद्ध में अकबर के संरक्षक बैरम खाँ ने हिंदू सम्राट हेमू को पराजित किया।\n3. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'खानवा युद्ध (1527 ई.)' का ऐतिहासिक संबंध 'शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय' से था।\n4. बहमनी सल्तनत के विघटन के बाद गोलकुंडा के कुतुबशाही सुल्तान मुहम्मद कुली कुतुब शाह ने हैदराबाद नगर तथा चारमीनार (1591) का निर्माण कराया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: 'खानवा युद्ध (1527 ई.)' का सही संबंध 'बाबर बनाम राणा सांगा (मेवाड़)' से था — 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।"},
  {"q":"[UPSC Prelims पैटर्न — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों पर विचार कीजिए:\n1. हल्दीघाटी युद्ध (1576 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\n2. चौसा का युद्ध (1539 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n3. करनाल का युद्ध (1739 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।) युग्म 2 सही (बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।) युग्म 3 सही (फरवरी 1739 में करनाल युद्ध में मुगल सेना कुछ घंटों में परास्त हुई और दिल्ली में भयानक कत्लेआम हुआ।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: इब्राहिम लोदी द्वारा बनवाया गया सिकंदर लोदी का मकबरा मकबरों के 'उद्यान युग' की शुरुआत करता है।\nकथन-2: टीपू सुल्तान ने श्रीरंगपट्टनम में फ्रांस के सम्मान में 'स्वतंत्रता का वृक्ष' लगाया, स्वयं को 'नागरिक टीपू' कहा और आधुनिक नौसेना बोर्ड व रेशम उत्पादन को बढ़ावा दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) इब्राहिम लोदी द्वारा बनवाया गया सिकंदर लोदी का मकबरा मकबरों के 'उद्यान युग' की शुरुआत करता है। (2) टीपू सुल्तान ने श्रीरंगपट्टनम में फ्रांस के सम्मान में 'स्वतंत्रता का वृक्ष' लगाया, स्वयं को 'नागरिक टीपू' कहा और आधुनिक नौसेना बोर्ड व रेशम उत्पादन को बढ़ावा दिया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सासाराम झील मकबरा   B. फर्नओ नूनिज (पुर्तगाल)\nC. आमुक्तमाल्यद   D. एकशरण संप्रदाय (असम)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["सासाराम झील मकबरा","आमुक्तमाल्यद","फर्नओ नूनिज (पुर्तगाल)","एकशरण संप्रदाय (असम)"],"correct":0,"explanation":"एकशरण संप्रदाय (असम) (15वीं-16वीं सदी), आमुक्तमाल्यद (16वीं सदी ई.), फर्नओ नूनिज (पुर्तगाल) (1535 ई.), सासाराम झील मकबरा (1545 ई.)। अतः सबसे अंत में सासाराम झील मकबरा।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है।\nकथन-2: क्षेत्रीय राज्य एवं संस्थापक के अंतर्गत 'हैदराबाद राज्य (आसफजाही)' का ऐतिहासिक संबंध 'सआदत खाँ 'बुरहान-उल-मुल्क'' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है।)। कथन-2 गलत है — 'हैदराबाद राज्य (आसफजाही)' का सही संबंध 'निजाम-उल-मुल्क (चिन किलिच खाँ)' से था — शकरखेड़ा युद्ध (1724) के बाद निजाम-उल-मुल्क ने दक्कन में स्वतंत्र हैदराबाद राज्य की नींव रखी।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-इंशा' का ऐतिहासिक संबंध 'धार्मिक मामले, वजीफे व राजनयिक/विदेश पत्राचार' से था।\n2. बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है।\n3. फिरोजशाह तुगलक ने अपने पूर्ववर्ती सुल्तानों की परंपरा के विपरीत सल्तनत में दास प्रथा को पूर्णतः अवैध घोषित कर समाप्त कर दिया।\n4. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'करनाल का युद्ध (1739 ई.)' का ऐतिहासिक संबंध 'बाबर बनाम राणा सांगा (मेवाड़)' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'अटाला मस्जिद (जौनपुर)' का ऐतिहासिक संबंध 'अलाउद्दीन खिलजी' से था।\n2. 1194 ई. में चंदावर (इटावा-फिरोजाबाद के निकट) के युद्ध में गौरी ने जयचंद्र को हराया।\n3. दक्कनी उदार सुल्तान इब्राहिम आदिल शाह II ('जगतगुरु') ने सरस्वती व गणेश वंदना सहित किताब-ए-नवरस लिखा।\n4. बरार सबसे पहले 1484-90 में अलग हुआ व 1574 में अहमदनगर में विलीन हुआ; बीदर सबसे अंत में अलग हुआ।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'अटाला मस्जिद (जौनपुर)' का सही संबंध 'इब्राहिम शाह शर्की ('पूर्व का सिराज')' से था — 1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. अकबर की मनसबदारी प्रणाली पूर्णतः वंशानुगत थी जिसमें सभी मनसबदारों को वेतन सदैव केवल चाँदी के टकों में ही मिलता था जागीर में नहीं।\n2. दीवान-ए-रिसालत का प्रमुख सद्र-उस-सुदूर विदेशी राजदूतों व धार्मिक अनुदान से जुड़ा था।\n3. मनसबदारी में 'जात' पद मनसबदार के व्यक्तिगत दर्जे व वेतन को तथा 'सवार' उसके द्वारा रखे जाने वाले घुड़सवारों की संख्या को निर्धारित करता था।\n4. 1722 में अवध का सूबेदार बनकर सआदत खाँ ने राजस्व सुधार कर स्वतंत्र अवध की नींव डाली।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: मनसबदारी पद वंशानुगत नहीं थे; मनसबदारों को वेतन नकद ('नकदी') या राजस्व क्षेत्र ('जागीरदार') दोनों रूपों में मिलता था।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'तराइन का प्रथम युद्ध (1191 ई.)' का ऐतिहासिक संबंध 'मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया' से था।\n2. गयासुद्दीन तुगलक ने खिज्र खाँ को हराकर भारत में लोदी वंश की नींव डाली और सल्तनत में नहरों का निर्माण पूर्णतः बंद करा दिया।\n3. गयासुद्दीन बलबन ने 'तुर्कान-ए-चहलगानी' (चालीसा गुट) का गठन कर तुर्क अमीरों को असीमित प्रशासनिक शक्तियाँ प्रदान कीं।\n4. पानीपत के प्रथम युद्ध (21 अप्रैल 1526) में बाबर ने उज्बेकों से सीखी 'तुलुगमा' युद्ध पद्धति और उस्मानी विधि से तोपें सजाकर इब्राहिम लोदी की विशाल सेना को हराया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (पानीपत के प्रथम युद्ध (21 अप्रैल 1526) में बाबर ने उज्बेकों से सीखी 'तुलुगमा' युद्ध पद्धति और उस्मानी विधि से तोपें सजाकर इब्राहिम लोदी की विशाल सेना को हराया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"'हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)' के ऐतिहासिक संदर्भ में 'राजस्व व सड़क सुधार' निम्नलिखित में से क्या है?","options":["तुर्की भाषा में आत्मकथा 'तुजुक-ए-बाबरी' (बाबरनामा) व 'मुबइयान' पद्य शैली; चारबाग शैली की शुरुआत","राजपूतों के साथ वैवाहिक-मित्रता नीति; गुजरात विजय (1572-73 — बुलंद दरवाजा, समुद्र दर्शन); असीरगढ़ (1601 — अंतिम विजय)","'पट्टा व कबूलियत', 'जरीबाना' व 'मुहसिलाना' कर, सड़क-ए-आजम (ग्रैंड ट्रंक रोड) व 1700 सरायें, सासाराम (बिहार) में अष्टकोणीय मकबरा","नूरजहाँ द्वारा पित्रादुरा (Pietra Dura) युक्त एत्मादुद्दौला मकबरा (पूर्णतः संगमरमर की प्रथम मुगल इमारत); उस्ताद मंसूर (पक्षी) व अबुल हसन चित्रकार"],"correct":2,"explanation":"हुमायूँ की जीवनी 'हुमायूँनामा' उसकी सौतेली बहन गुलबदन बेगम ने लिखी थी। 1556 ई. में दिल्ली के 'दीनपनाह' पुस्तकालय ('शेर मंडल') की सीढ़ियों से गिरकर हुमायूँ की मृत्यु हुई।"},
  {"q":"[PSC/CDS युग्म पहचान — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अटाला मस्जिद (जौनपुर) : इब्राहिम शाह शर्की ('पूर्व का सिराज')\n2. एत्मादुद्दौला का मकबरा (आगरा) : ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा\n3. गयासुद्दीन तुगलक मकबरा : भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\n4. सिकंदर लोदी का मकबरा (1517) : अलाउद्दीन खिलजी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: 1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है। (अन्य सही युग्म: एत्मादुद्दौला का मकबरा (आगरा)→नूरजहाँ (जहाँगीर काल, 1626), गयासुद्दीन तुगलक मकबरा→ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा, सिकंदर लोदी का मकबरा (1517)→भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन))।"},
  {"q":"[UPSC Prelims पैटर्न — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चौसा का युद्ध (1539 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n2. हल्दीघाटी युद्ध (1576 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\n3. करनाल का युद्ध (1739 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।) युग्म 2 सही (18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।) युग्म 3 सही (फरवरी 1739 में करनाल युद्ध में मुगल सेना कुछ घंटों में परास्त हुई और दिल्ली में भयानक कत्लेआम हुआ।)।"}
]);
